// Build the daily sovereignty report DETERMINISTICALLY.
//
// No language model is involved - not even the local one. A compliance artifact
// must be byte-reproducible from the same probe responses, and an LLM summary
// would be neither reproducible nor auditable.
//
// Every section is labelled with an explicit status so a missing endpoint can
// never be silently reported as a healthy one:
//   ok               - probe answered and the value is trustworthy
//   declared         - endpoint answered, but the value is a static declaration
//   not_implemented  - endpoint does not exist yet (FUTURE API REQUIRED)
//   unavailable      - endpoint exists but did not answer

const ctx = $('Set: Run Context').first().json;

function probe(nodeName) {
  try {
    const r = $(nodeName).first().json || {};
    const status = Number(r.statusCode || 0);
    if (!status)                  return { status: 'unavailable',     http: null,   body: null, detail: String(r.error || r.message || 'no response').slice(0, 200) };
    if (status === 404 || status === 501) return { status: 'not_implemented', http: status, body: null, detail: 'endpoint absent' };
    if (status >= 400)            return { status: 'unavailable',     http: status, body: null, detail: `HTTP ${status}` };
    return { status: 'ok', http: status, body: r.body, detail: null };
  } catch (e) {
    return { status: 'unavailable', http: null, body: null, detail: 'probe did not execute' };
  }
}

const sov      = probe('Probe: Sovereignty Proof');
const health   = probe('Probe: Backend Health');
const models   = probe('Probe: Local Models');
const qdrant   = probe('Probe: Qdrant Collection');
const approval = probe('Probe: Pending Approvals');
const audit    = probe('Probe: Audit Chain (FUTURE)');

// --- external AI calls -------------------------------------------------
const sovBody = sov.body || {};
const externalCalls = {
  value: sovBody.external_ai_calls ?? sovBody.external_calls ?? null,
  // Phase 3A guide: /sovereignty/proof is a Phase 2 STATIC declaration,
  // not network attestation or a measured outbound-call counter.
  status: sov.status === 'ok' ? 'declared' : sov.status,
  caveat: 'Static declaration from the Phase 2 endpoint. NOT a measured egress counter. Network-level proof still comes from the container egress policy, not from this number.'
};

// --- local model status ------------------------------------------------
const modelList = (models.body && Array.isArray(models.body.models)) ? models.body.models : [];
const localModels = {
  status: models.status,
  runtime_reachable: models.status === 'ok',
  model_count: models.status === 'ok' ? modelList.length : null,
  models: modelList.map((m) => ({ name: m.name || m.model || null, size_bytes: m.size ?? null, modified_at: m.modified_at ?? null })).slice(0, 50)
};

// --- indexed documents -------------------------------------------------
const qres = (qdrant.body && qdrant.body.result) ? qdrant.body.result : {};
const indexed = {
  status: qdrant.status,
  collection: ctx.qdrant_collection,
  points_count: qres.points_count ?? null,
  indexed_vectors_count: qres.indexed_vectors_count ?? null,
  collection_status: qres.status ?? null,
  caveat: 'points_count counts CHUNKS, not documents. A document-level count needs GET /knowledge/stats (FUTURE API REQUIRED).'
};

// --- audit chain -------------------------------------------------------
const auditBody = audit.body || {};
const auditChain = {
  status: audit.status,
  chain_valid: auditBody.chain_valid ?? null,
  entries_verified: auditBody.entries_verified ?? null,
  last_hash: auditBody.last_hash ?? null,
  caveat: audit.status === 'not_implemented'
    ? 'GET /audit/verify does not exist yet, and README states audit hash chaining is absent in the current phase. Chain integrity is UNVERIFIED, not verified-good.'
    : null
};

// --- pending approvals -------------------------------------------------
const ab = approval.body;
const apList = Array.isArray(ab) ? ab : ((ab && (ab.items || ab.approvals || ab.results)) || []);
const approvals = {
  status: approval.status,
  pending_count: approval.status === 'ok' ? apList.length : null,
  oldest_pending_at: approval.status === 'ok' && apList.length
    ? apList.map((a) => a.created_at).filter(Boolean).sort()[0] || null
    : null,
  caveat: 'Identifiers and counts only. No approval CONTENT is written into this report.'
};

const sections = { externalCalls, localModels, indexed, auditChain, approvals };
const degraded = Object.values(sections).some((s) => s.status === 'unavailable');
const incomplete = Object.values(sections).some((s) => s.status === 'not_implemented');

const report = {
  report_type: 'daily_sovereignty_status',
  schema_version: '1.0',
  report_date: ctx.report_date,
  generated_at: ctx.generated_at,
  generated_by: 'n8n:WB-03 (deterministic, no LLM)',
  run_id: ctx.run_id,
  overall: degraded ? 'degraded' : (incomplete ? 'ok_with_gaps' : 'ok'),
  backend_health: { status: health.status, payload: health.body ?? null },
  external_ai_calls: externalCalls,
  local_models: localModels,
  indexed_documents: indexed,
  audit_chain: auditChain,
  pending_approvals: approvals,
  disclaimer: 'Operational status report. It does not certify process safety, does not authorise any plant action, and asserts nothing about physical equipment state.'
};

// --- Markdown rendering ------------------------------------------------
const badge = (s) => ({ ok: 'OK', declared: 'DECLARED', not_implemented: 'NOT IMPLEMENTED', unavailable: 'UNAVAILABLE' }[s] || String(s).toUpperCase());
const v = (x) => (x === null || x === undefined ? '_not available_' : String(x));

const md = [
  `# Sovereign Workbench - Daily Status Report`,
  ``,
  `**Date:** ${report.report_date}  `,
  `**Generated:** ${report.generated_at} (deterministic, no AI service used)  `,
  `**Overall:** ${report.overall.toUpperCase()}`,
  ``,
  `| Item | Status | Value |`,
  `| --- | --- | --- |`,
  `| External AI calls | ${badge(externalCalls.status)} | ${v(externalCalls.value)} |`,
  `| Backend health | ${badge(health.status)} | ${v((health.body||{}).status)} |`,
  `| Local model runtime | ${badge(localModels.status)} | ${v(localModels.model_count)} model(s) loaded |`,
  `| Indexed chunks (${indexed.collection}) | ${badge(indexed.status)} | ${v(indexed.points_count)} |`,
  `| Audit chain | ${badge(auditChain.status)} | ${v(auditChain.chain_valid)} |`,
  `| Pending approvals | ${badge(approvals.status)} | ${v(approvals.pending_count)} |`,
  ``,
  `## Local models`,
  localModels.models.length ? localModels.models.map((m) => `- ${m.name}`).join('\n') : '_none reported_',
  ``,
  `## Caveats that must not be dropped`,
  `- ${externalCalls.caveat}`,
  `- ${indexed.caveat}`,
  auditChain.caveat ? `- ${auditChain.caveat}` : `- Audit chain reported by the backend; independent re-verification is recommended.`,
  `- ${approvals.caveat}`,
  ``,
  `## Disclaimer`,
  report.disclaimer,
  ``
].join('\n');

const dir = $env.WB_REPORT_DIR || '/data/n8n/reports/sovereignty';

return [{
  json: {
    ...report,
    md_path: `${dir}/sovereignty-${report.report_date}.md`,
    json_path: `${dir}/sovereignty-${report.report_date}.json`
  },
  binary: {
    md:   await this.helpers.prepareBinaryData(Buffer.from(md, 'utf8'), `sovereignty-${report.report_date}.md`, 'text/markdown'),
    json: await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(report, null, 2), 'utf8'), `sovereignty-${report.report_date}.json`, 'application/json')
  }
}];
